_ARG = re.compile(r"<(?:\w+:)?(\w+)>")


def reverse(
    name: str,
    args: list[Any] | tuple[Any, ...] = (),
    kwargs: dict[str, Any] | None = None,
) -> str:
    """The path Django gave ``name``, its converters filled in order or by name."""
    pattern = ROUTES[name]
    given = list(args)
    named = dict(kwargs or {})

    def fill(match: re.Match[str]) -> str:
        key = match.group(1)
        return str(named.pop(key) if key in named else given.pop(0))

    return _ARG.sub(fill, pattern)
